     2	
     3	import java.security.interfaces.RSAPrivateKey;
     4	
     5	import org.jose4j.jwa.AlgorithmConstraints;
     6	import org.jose4j.jwk.JsonWebKey;
     7	import org.jose4j.jwk.JsonWebKeySet;
     8	import org.jose4j.jwk.RsaJsonWebKey;
     9	import org.jose4j.jwk.VerificationJwkSelector;
    10	import org.jose4j.jws.AlgorithmIdentifiers;
    11	import org.jose4j.jws.JsonWebSignature;
    12	import org.jose4j.jwx.HeaderParameterNames;
    13	import org.jose4j.lang.JoseException;
    14	import org.springframework.http.HttpStatus;
    15	
    16	import com.finbit.fiuadapter.jwssignature.exception.JWSSignatureException;
    17	
    18	import lombok.extern.slf4j.Slf4j;
    19	
    20	/**
    21	 * @author manjunathr Created on 22-06-2020
    22	 *
    23	 *         This util is used for the JWS signature operations
    24	 */
    25	@Slf4j
    26	public class JwsUtil {
    27	
    28	    public String sign( String data, JsonWebKey jsonWebKey ) throws JoseException
    29	    {
    30	        // Create a new JsonWebSignature object for the signing
    31	        JsonWebSignature signer = buildJWSigner(data, jsonWebKey);
    32	        return signer.getDetachedContentCompactSerialization();
    33	    }
    34	
    35	    public JsonWebKey selectKeyFromSet( JsonWebKeySet jsonWebKeySet )
    36	    {
    37	        return jsonWebKeySet.getJsonWebKeys().get(0);
    38	    }
    39	
    40	    private JsonWebSignature buildJWSigner( String payload, JsonWebKey jsonWebKey )
    41	    {
    42	        JsonWebSignature signer = new JsonWebSignature();
    43	        // The content is the payload of the JWS
    44	        signer.setPayload(payload);
    45	
    46	        // Set the signature algorithm on the JWS
    47	        signer.setAlgorithmHeaderValue(AlgorithmIdentifiers.RSA_USING_SHA256);
    48	
    49	        // The private key is used to sign
    50	        signer.setKey(extractRSAPrivateKey(jsonWebKey));
    51	        signer.setKeyIdHeaderValue(jsonWebKey.getKeyId());
    52	
    53	        // Set the "b64" header to false, which indicates that the payload is not
    54	        // encoded
    55	        // when calculating the signature (per RFC 7797)
    56	        signer.getHeaders().setObjectHeaderValue(HeaderParameterNames.BASE64URL_ENCODE_PAYLOAD, false);
    57	
    58	        // RFC 7797 requires that the "b64" header be listed as critical
    59	        signer.setCriticalHeaderNames(HeaderParameterNames.BASE64URL_ENCODE_PAYLOAD);
    60	        return signer;
    61	    }
    62	
    63	    /**
    64	     * This method validates the detached json web signature with the supplied payload.
    65	     *
    66	     * @param detachedSignature
    67	     * @param payload
    68	     * @throws Exception
    69	     *             - if signature validation fails.
    70	     */
    71	    public boolean validateSign( String detachedSignature, String payload, JsonWebKeySet jsonWebKeySet )
    72	            throws JoseException
    73	    {
    74	
    75	        // Use a JsonWebSignature object to verify the signature
    76	        JsonWebSignature verifierJws = new JsonWebSignature();
    77	
    78	        // Set the algorithm constraints based on what is agreed upon or expected from
    79	        // the sender
    80	        verifierJws.setAlgorithmConstraints(new AlgorithmConstraints(AlgorithmConstraints.ConstraintType.WHITELIST,
    81	                AlgorithmIdentifiers.RSA_USING_SHA256));
    82	
    83	        // The JWS with detached content is the compact serialization
    84	        verifierJws.setCompactSerialization(detachedSignature);
    85	
    86	        // The unencoded detached content is the payload
    87	        verifierJws.setPayload(payload);
    88	
    89	        VerificationJwkSelector jwkSelector = new VerificationJwkSelector();
    90	
    91	        RsaJsonWebKey jwk = (RsaJsonWebKey) jwkSelector.select(verifierJws, jsonWebKeySet.getJsonWebKeys());
    92	
    93	        if(jwk == null){
    94	            return false;
    95	        }
    96	
    97	        // The public key is used to verify the signature
    98	        // This should be the public key of the sender.
    99	        verifierJws.setKey(jwk.getPublicKey());
   100	
   101	        // Check the signature
   102	        return verifierJws.verifySignature();
   103	    }
   104	
   105	    private RSAPrivateKey extractRSAPrivateKey( JsonWebKey jsonWebKey )
   106	    {
   107	        return ((RsaJsonWebKey) jsonWebKey).getRsaPrivateKey();
   108	    }
   109	
   110	    public JsonWebKeySet buildJwkKeysFromJson( String keys ) throws JoseException
   111	    {
   112	        return new JsonWebKeySet(keys);
   113	    }
   114	
   115	    public void validateJsonKeySet( String jsonKeySet ) throws JWSSignatureException
   116	    {
   117	        try
   118	        {
   119	            log.info("Validating the json key set");
   120	            JwsUtil jwsUtil = new JwsUtil();
   121	            JsonWebKeySet jsonWebKeySet = jwsUtil.buildJwkKeysFromJson(jsonKeySet);
   122	            JsonWebKey selectedKey = jwsUtil.selectKeyFromSet(jsonWebKeySet);
   123	
   124	            String sign = jwsUtil.sign(jsonKeySet, selectedKey);
   125	
   126	            if( !jwsUtil.validateSign(sign, jsonKeySet, jsonWebKeySet) )
   127	            {
   128	                log.error("Invalid Key Set");
   129	                throw new JWSSignatureException(HttpStatus.BAD_REQUEST.getReasonPhrase(), "Invalid Key Set",
   130	                        HttpStatus.BAD_REQUEST);
   131	            }
   132	        }
   133	        catch( JWSSignatureException e )
   134	        {
   135	            throw e;
   136	        }
   137	        catch( Exception e )
   138	        {
   139	            log.error("Invalid Key Set", e);
   140	            throw new JWSSignatureException(HttpStatus.BAD_REQUEST.getReasonPhrase(), "Invalid Key Set",
   141	                    HttpStatus.BAD_REQUEST);
   142	        }
   143	    }
   144	}
