import com.finbit.fiuadapter.webservice.utils.*;
import com.finbit.fiuadapter.webservice.constants.GeneralConstants;
import java.util.*;

public class Sanity {
    public static void main(String[] a) throws Exception {
        System.out.println("--- #4471 UUID validation ---");
        int ok=0; for(int i=0;i<2000;i++) if(UUIDGenerator.regaxUUIDvalidation(UUIDGenerator.generateUUID())) ok++;
        System.out.println("canonical v4 accepted: "+ok+"/2000");
        // the previously-failing edge: full 12-char final group
        System.out.println("explicit v4 accepted : "+UUIDGenerator.regaxUUIDvalidation("f81d4fae-7dec-41d0-9765-00a0c91e6bf6"));
        System.out.println("malformed still refused:");
        for(String bad: new String[]{"", "not-a-uuid", "f81d4fae-7dec-41d0-9765-00a0c91e6bf",
                "f81d4fae-7dec-41d0-9765-00a0c91e6bf67", "f81d4fae7dec41d0976500a0c91e6bf6",
                "f81d4fae-7dec-11d0-9765-00a0c91e6bf6", "f81d4fae-7dec-41d0-c765-00a0c91e6bf6"})
            System.out.println("  ["+bad+"] -> "+UUIDGenerator.regaxUUIDvalidation(bad));

        System.out.println("--- #4488 afternoon timestamps ---");
        // 2024-03-05T13:47:22.123Z
        long pm = 1709646442123L;
        System.out.println("13:47 UTC -> "+DateTimeUtil.getISOTimeStamp(pm));
        System.out.println("01:47 UTC -> "+DateTimeUtil.getISOTimeStamp(pm - 12*3600_000L));
        System.out.println("23:59 UTC -> "+DateTimeUtil.getISOTimeStamp(1709251199000L));
        System.out.println("00:00 UTC -> "+DateTimeUtil.getISOTimeStamp(1709164800000L));
        System.out.println("12:00 UTC -> "+DateTimeUtil.getISOTimeStamp(1709208000000L));

        System.out.println("--- base64url payload decoding ---");
        // payload whose standard-base64 form uses '+' and '/', i.e. base64url uses '-' and '_'
        String json = "{\"consentId\":\"a\\u00ff\\u00fe~?>\"}";
        String b64url = Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes("UTF-8"));
        System.out.println("segment contains -/_ : "+(b64url.contains("-")||b64url.contains("_"))+"  ["+b64url+"]");
        System.out.println("decoded ok           : "+Base64Decoder.getDecodedObject(b64url, Object.class));

        System.out.println("--- blank field validation ---");
        for(String s: new String[]{null,"","   ","\t\n","null","ok"," ok "})
            System.out.println("  ["+s+"] -> "+NullEmptyUtils.isNullorEmpty(s));
        System.out.println("  isRowNull([\" \",\"\"]) -> "+NullEmptyUtils.isRowNull(new String[]{" ",""}));
    }
}
EOF
